SELECT c.code FROM courses c JOIN (
    SELECT course_id, AVG(score) AS avg_score
    FROM marks
    GROUP BY course_id
) m ON c.course_id = m.course_id WHERE m.avg_score < 65;

SELECT first_name, last_name FROM students s JOIN (
    SELECT AVG(score) AS avg_score FROM marks
) AS m ON s.student_id = m.student_id WHERE s.student_id IN (
    SELECT student_id FROM marks GROUP BY student_id HAVING AVG(score) > (SELECT AVG(score) FROM marks)
)

